function t(){gsap.utils.toArray(".section--hero").forEach(o=>{let e=o.querySelector(".wp-block-cover__image-background");e&&gsap.effects.parallax(e,{yFrom:0,yTo:5,scaleFrom:1,scaleTo:1.04,parent:o,start:"top top"})})}function s(){gsap.utils.toArray(".section--mission").forEach(o=>{let e=o.querySelector(".wp-block-cover__image-background");e&&gsap.effects.parallax(e,{parent:o})})}window.addEventListener("load",()=>{t(),s()});
